INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1402902', 'Dervish War', 'The Dervish War was a conflict in the Horn of Africa, between the Dervish State, and the imperial powers of Abyssinia, Britain and Italy, initially from 1900 to 1904, which was followed by a peace treaty-protectorate period with the Italians from 1905, other diplomatic measures in the following years, and a resumption of conflict with the colonial powers from 1913 to 1920. The opening battle of the rebellion saw the Dervish attack the Ethiopian garrison at Jigjiga in March 1900 and take control of parts of the eastern Ogaden region.', 1900, NULL, NULL, 1920, NULL, NULL, 'year', '1900–1920', 50, 'https://en.wikipedia.org/wiki/Dervish_War'),
  ('Q1271059', 'Shifta War', 'The Shifta War or Gaf Daba (1963–1967) was a secessionist conflict in which ethnic Somalis, Muslim Borana, Sakuye, Gabbra and Rendille in the then Northern Frontier District (NFD) of Kenya attempted to join Somalia. The Kenyan government named the conflict "shifta", after the Swahili word for "bandit", as part of a propaganda effort.', 1963, NULL, NULL, 1967, NULL, NULL, 'year', '1963–1967', 47, 'https://en.wikipedia.org/wiki/Shifta_War'),
  ('Q55600802', '1964 Ethiopian-Somali Border War', 'The 1964 Ethiopian–Somali Border War, also known as the First Ogaden War marked the first military conflict between the newly established Somali Republic and the Ethiopian Empire, lasting from February to April 1964. The border conflict was preceded by a rebellion in the Ogaden region during mid-1963 that was waged by Somalis seeking self-determination from imperial rule.', 1964, NULL, NULL, 1964, 4, 2, 'year', '1964', 41, 'https://en.wikipedia.org/wiki/1964_Ethiopian%E2%80%93Somali_Border_War'),
  ('Q48733987', '1969 Somali coup d''état', 'The 1969 Somali coup d''état was a bloodless military takeover of the Somali Republic on 21 October 1969, led by Somali National Army officers of the Supreme Revolutionary Council under General Siad Barre. After the assassination of President Abdirashid Shermarke in Las Anod, the Somali National Army under Barre''s command stormed Mogadishu, seized key government buildings, and demanded the resignation of the country''s leaders.', 1969, 10, 21, NULL, NULL, NULL, 'day', '21 October 1969', 45, 'https://en.wikipedia.org/wiki/1969_Somali_coup_d''%C3%A9tat'),
  ('Q318250', 'Ogaden War', 'The Ogaden War, also known as the Ethio-Somali War (Somali: Dagaalkii Xoraynta Soomaali Galbeed, Amharic: የኢትዮጵያ ሶማሊያ ጦርነት, romanized: ye’ītiyop’iya somalīya t’orinet), was a military conflict between Somalia and Ethiopia fought from July 1977 to March 1978 over control of the sovereignty of the Ogaden region. Somalia launched an invasion in support of the Western Somali Liberation Front (WSLF) insurgency, triggering a broader inter-state war.', 1977, 7, 12, 1978, 3, 23, 'day', '12 July 1977 – 23 March 1978', 73, 'https://en.wikipedia.org/wiki/Ogaden_War'),
  ('Q652284', '1982 Ethiopian–Somali Border War', 'The Ethiopian–Somali Border War took place from June 1982 to August 1983, when Ethiopia launched a large-scale invasion of central Somalia. Backed by warplanes and armored units, Ethiopia deployed a 10,000-man force alongside thousands of Somali Salvation Democratic Front (SSDF) rebels.', 1982, NULL, NULL, 1982, 8, NULL, 'year', '1982', 50, 'https://en.wikipedia.org/wiki/1982_Ethiopian%E2%80%93Somali_Border_War'),
  ('Q243620', 'Somali Civil War', 'The Somali Civil War (Somali: Dagaalkii Sokeeye ee Soomaaliya; Arabic: الحرب الأهلية الصومالية al-ḥarb al-’ahliyya aṣ-ṣūmāliyya) is an ongoing civil war that is taking place in Somalia. It grew out of resistance to the military junta led by Siad Barre during the 1980s.', 1991, 1, 26, NULL, NULL, NULL, 'day', '26 January 1991', 76, 'https://en.wikipedia.org/wiki/Somali_Civil_War'),
  ('Q1637882', 'Famine in Somalia', 'The 1992 famine in Somalia resulted from a severe drought and devastation caused by warring factions in southern Somalia, primarily the Somali National Front, in the fertile inter-riverine breadbasket between the Jubba and Shebelle rivers. The resulting famine primarily affected residents living in the riverine area, predominantly in Bay Region, and those internally displaced by the civil war.', 1991, 12, NULL, 1992, 12, NULL, 'month', 'December 1991 – December 1992', 37, 'https://en.wikipedia.org/wiki/1992_famine_in_Somalia'),
  ('Q52226', 'Battle of Mogadishu', 'The Battle of Mogadishu (Somali: Maalintii Rangers, lit. ''Day of the Rangers''), also known as the Black Hawk Down Incident, was part of Operation Gothic Serpent. It was fought on 3–4 October 1993, in Mogadishu, Somalia, between forces of the United States—supported by UNOSOM II—against Somali National Alliance (SNA) fighters and other insurgents in south Mogadishu.', 1993, 10, 3, 1993, 10, 4, 'day', '3 October 1993 – 4 October 1993', 69, 'https://en.wikipedia.org/wiki/Battle_of_Mogadishu_(1993)'),
  ('Q1778229', 'United Nations Operation in Somalia II', 'The United Nations Operation in Somalia II (UNOSOM II) was the second phase of the United Nations intervention in Somalia and took place from March 1993 until March 1995, following the outbreak of the Somali Civil War in 1991. UNOSOM II carried on from the transitory United States-controlled (UN-sanctioned) Unified Task Force (UNITAF), which had been preceded by UNOSOM I. Notably, UNOSOM II embarked on a nation-building mission, diverging from its predecessors.', 1993, 3, NULL, 1995, 3, 28, 'month', 'March 1993 – 28 March 1995', 56, 'https://en.wikipedia.org/wiki/United_Nations_Operation_in_Somalia_II'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q1072042', 'War in Somalia', 'The Ethiopian invasion of Somalia, also known as the Ethiopian occupation of Somalia was an armed conflict lasting from mid-2006 to early 2009. It began when Ethiopian military forces, supported by the United States, invaded Somalia to depose the Islamic Courts Union (ICU) and install the Transitional Federal Government (TFG).', 2006, 12, 20, 2009, 1, 30, 'day', '20 December 2006 – 30 January 2009', 57, 'https://en.wikipedia.org/wiki/War_in_Somalia_(2006%E2%80%932009)'),
  ('Q1323183', 'capture of Mogadishu', 'The Fall of Mogadishu was a major episode of the Ethiopian invasion of Somalia. It occurred on 28 December 2006, when the Ethiopian National Defence Forces (ENDF) entered the capital in support of the Transitional Federal Government (TFG), following the withdrawal of Islamic Courts Union (ICU) troops deployed in southern and central Somalia.', 2006, 12, 28, NULL, NULL, NULL, 'day', '28 December 2006', 41, 'https://en.wikipedia.org/wiki/Fall_of_Mogadishu'),
  ('Q1478359', 'Battle of Jilib', 'The Battle of Jilib took place on the last day of 2006 during the Ethiopian invasion of Somalia. It was fought when Ethiopian National Defence Force (ENDF) troops and Transitional Federal Government (TFG) militia launched an offensive on the town of Jilib, held by the Islamic Courts Union (ICU).', 2006, 12, 31, 2007, 1, 1, 'day', '31 December 2006 – 1 January 2007', 41, 'https://en.wikipedia.org/wiki/Battle_of_Jilib'),
  ('Q2275247', 'Battle of Mogadishu', 'The Second Battle of Mogadishu was fought for control of Somalia''s capital city, Mogadishu. The opposing forces were the Alliance for the Restoration of Peace and Counter-Terrorism (ARPCT), and militia loyal to the Islamic Courts Union (ICU).', 2006, NULL, NULL, 2006, 7, 11, 'year', '2006', 37, 'https://en.wikipedia.org/wiki/Battle_of_Mogadishu_(2006)'),
  ('Q3495636', 'Battle of Baidoa', 'The Battle of Baidoa began on 20 December 2006 when the Somali transitional federal government forces (TFG) allied with Ethiopian forces stationed there attacked advancing Islamic Courts Union (ICU) forces along with 500 alleged Eritrean troops and mujahideen arrayed against them. The battle began with most reports depicting the government forces defecting and its position on the verge of collapse.', 2006, NULL, NULL, 2006, 12, 26, 'year', '2006', 41, 'https://en.wikipedia.org/wiki/Battle_of_Baidoa'),
  ('Q4870412', 'Battle of Bandiradley', 'The Battle of Bandiradley in Somalia began on December 23, 2006, when Puntland and Ethiopian forces, along with faction leader Abdi Qeybdid, fought Islamic Courts Union (ICU) militants defending Bandiradley. The fighting pushed the Islamists out of Bandiradley and over the border south into Adado district, Galgadud region, by December 25.', 2006, NULL, NULL, 2006, 12, 25, 'year', '2006', 34, 'https://en.wikipedia.org/wiki/Battle_of_Bandiradley'),
  ('Q4870424', 'Battle of Bargal', 'The Battle of Bargal occurred in June 2007 around the town of Bargal in the northern province of Bari, in the semi-autonomous region of Puntland.', 2007, NULL, NULL, 2007, 6, 3, 'year', '2007', 34, 'https://en.wikipedia.org/wiki/Battle_of_Bargal_(2007)'),
  ('Q5432162', 'Fall of Kismayo', 'The fall of Kismayo occurred on January 1, 2007, Ethiopian military forces backing the Transitional Federal Government entered the Somali city of Kismayo unopposed. It came after the Islamic Courts Union''s forces faltered and fled in the Battle of Jilib.', 2007, 1, 1, NULL, NULL, NULL, 'day', '1 January 2007', 34, 'https://en.wikipedia.org/wiki/Fall_of_Kismayo'),
  ('Q4871757', 'Battle of Mogadishu', 'The 2008 Battle of Mogadishu began when soldiers from Ethiopian National Defence Force (ENDF) entered parts of the capital held by the insurgency on 19 April, sparking heavy street fighting in the northern part of the city. The battle spread out over several districts of Mogadishu, predominantly Daynile, Yaaqshiid and Huriwa resulting in the most fierce fighting between the Ethiopians and the insurgency since the start of 2008.', 2008, NULL, NULL, 2008, 4, 20, 'year', '2008', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mogadishu_(2008)'),
  ('Q7509849', 'Siege of Baidoa', 'The siege of Baidoa was a military confrontation lasting from July 2008 to January 2009 during the Ethiopian occupation of Somalia, during which al-Shabaab laid siege to the headquarters of the Ethiopian backed Somali Transitional Federal Government (TFG). During January 2009, the first TFG collapsed and Al-Shabaab overran the seat of the government in Baidoa.', 2008, 7, 8, 2009, 1, 26, 'day', '8 July 2008 – 26 January 2009', 34, 'https://en.wikipedia.org/wiki/Siege_of_Baidoa'),
  ('Q1052332', 'Somali Civil War', 'The ongoing phase of the Somali Civil War began in 2009 and is concentrated in southern and central Somalia, primarily between the forces of the Federal Government of Somalia (FGS), assisted by African Union peacekeeping forces, and the Islamist militant group al-Shabaab, which pledged allegiance to al-Qaeda in 2012. During the insurgency that followed the 2006 Ethiopian invasion of Somalia, al-Shabaab rose to prominence and made major territorial gains.', 2009, 1, 31, NULL, NULL, NULL, 'day', '31 January 2009', 59, 'https://en.wikipedia.org/wiki/Somali_Civil_War_(2009%E2%80%93present)'),
  ('Q4872417', 'Battle of South Mogadishu', 'The Battle of South Mogadishu occurred in the Somali capital of Mogadishu on February 24, 2009. The battle''s name includes South, when referenced, in order to distinguish it amongst the nine major Battles of Mogadishu during the decades long Somali Civil War.', 2009, NULL, NULL, 2009, 2, 25, 'year', '2009', 34, 'https://en.wikipedia.org/wiki/Battle_of_South_Mogadishu'),
  ('Q1140554', 'Battle of Mogadishu', 'The Battle of Mogadishu (2010–11) began on 23 August 2010 when al-Shabaab insurgents began attacking government and African Union Mission to Somalia (AMISOM) positions in the Somali capital of Mogadishu. Al-Shabaab began its offensive after its spokesman said the group was declaring a "massive war" on troops sent by AMISOM, describing its 6,000 peacekeepers as "invaders".', 2010, 8, 23, 2011, 8, 6, 'day', '23 August 2010 – 6 August 2011', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mogadishu_(2010%E2%80%932011)'),
  ('Q55615630', 'Kampala Accord', 'The Kampala Accord was an agreement made in Kampala, Uganda in line with the Transitional Federal Charter of the Somali Republic to bring an end to the transitional phase of the Transitional Federal Government on 20 August 2011. It was signed on 9 June 2011 by HE Sharif Sheikh Ahmed, President of the Transitional Federal Government, Hon Sharif Hassan Sheikh Aden, Speaker of the Transitional Federal Parliament, H.E. Yoweri Kaguta Museveni, President of the Replublic of Uganda and Dr Augustine Mahiga, Special Representative of the Secretary General of the United Nations.', 2011, 6, 9, NULL, NULL, NULL, 'day', '9 June 2011', 26, 'https://en.wikipedia.org/wiki/Kampala_Accord'),
  ('Q4871455', 'Battle of Kismayo', 'The Battle of Kismayo was an offensive led by the Kenya Defence Forces, under the codename Operation Sledge Hammer, to seize the port city of Kismayo, Somalia, from Al-Shabaab from 28 September 2012. Members of the Raskamboni movement militia were part of the amphibious force.', 2012, 9, 25, 2012, 10, 1, 'day', '25 September 2012 – 1 October 2012', 39, 'https://en.wikipedia.org/wiki/Battle_of_Kismayo_(2012)'),
  ('Q22078513', 'Battle of El Adde', 'The Battle of El Adde took place on 15 January 2016. Al-Shabaab militants launched an attack on a Kenyan-run AMISOM army base in the town of El Adde, Gedo, Somalia.', 2016, 1, 15, NULL, NULL, NULL, 'day', '15 January 2016', 34, 'https://en.wikipedia.org/wiki/Battle_of_El_Adde'),
  ('Q22450721', 'Daallo Airlines Flight 3159', 'Daallo Airlines Flight 159 was a scheduled international passenger flight operated by Somali-owned Daallo Airlines. On 2 February 2016, the flight was the target of a terrorist attack, and an explosion occurred on board the aircraft 20 minutes after it took off from Mogadishu.', 2016, 2, 2, NULL, NULL, NULL, 'day', '2 February 2016', 55, 'https://en.wikipedia.org/wiki/Daallo_Airlines_Flight_159'),
  ('Q28913639', '2017 Somalian drought', 'The 2017 Somali drought was a severe drought that affected Somalia between late 2016 and early 2018, following consecutive seasons of low rainfall across the country. The drought brought widespread crop failure, livestock deaths, and displacement, resulting in one of the biggest humanitarian crises in Somalia since the 2011 East African drought.', 2017, NULL, NULL, NULL, NULL, NULL, 'year', '2017', 41, 'https://en.wikipedia.org/wiki/2017_Somali_drought'),
  ('Q117190940', '2023 Las Anod conflict', 'The Las Anod conflict (Somali: Dagaalkii Laascaanood) was an armed conflict between Somaliland and Khaatumo SSC (Sool, Sanaag and Cayn regions) forces of the Dhulbahante clan around Las Anod, the capital of the Sool region. Local tensions escalated in late 2022 following the assassination of civil leaders in Las Anod, culminating in fighting that erupted on 6 February 2023 after Somaliland security forces violently cracked down on civilian protests.', 2023, 2, 6, 2023, 8, 28, 'day', '6 February 2023 – 28 August 2023', 39, 'https://en.wikipedia.org/wiki/Las_Anod_conflict_(2023)'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods');
